package zone.moddev.mc.ironagearchitecture.probe;

import java.util.*;
import java.nio.file.*;
import com.google.gson.GsonBuilder;
import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.item.EntityItem;
import net.minecraft.init.*;
import net.minecraft.item.*;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.server.MinecraftServer;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
import net.minecraft.world.WorldServer;
import net.minecraftforge.common.util.*;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.gameevent.TickEvent;
import zone.moddev.mc.ironagearchitecture.*;
import zone.moddev.mc.ironagearchitecture.block.*;
import zone.moddev.mc.ironagearchitecture.roof.*;

/** Native server construction, interruption and inventory checks on a disposable world. */
public final class WorkbenchProbe {
    private final WorldServer world;private final MinecraftServer server;
    private final FakePlayer player;private ArchitectWorkbench.Desk desk;
    private int phase,ticks,cost,stock,maxChanges;private long previousChanges;
    private final Map<String,Object> result=new LinkedHashMap<>();
    private WorkbenchProbe(WorldServer world,MinecraftServer server){this.world=world;this.server=server;player=FakePlayerFactory.getMinecraft(world);if(player.connection==null)player.connection=new net.minecraft.network.NetHandlerPlayServer(server,new net.minecraft.network.NetworkManager(net.minecraft.network.EnumPacketDirection.SERVERBOUND),player);player.capabilities.isCreativeMode=false;player.setPosition(1060,85,1060);}
    public static void start(WorldServer world,MinecraftServer server){net.minecraftforge.fml.common.FMLCommonHandler.instance().bus().register(new WorkbenchProbe(world,server));}
    private static void require(boolean ok,String message){if(!ok)throw new IllegalStateException(message);}
    public static ArchitectWorkbench.Desk floor(WorldServer w,int x,int z,int width,int length,int wood){for(int a=x-2;a<x+width+2;a++)for(int b=z-2;b<z+length+2;b++){w.getChunkFromChunkCoords(a>>4,b>>4);for(int y=80;y<110;y++)w.setBlockToAir(new BlockPos(a,y,b));}for(int a=x;a<x+width;a++)for(int b=z;b<z+length;b++)w.setBlockState(new BlockPos(a,80,b),ArchitectureBlocks.findFloor(ArchitectureBlocks.WOODS[wood],FloorShape.FULL,null).getDefaultState(),2);BlockPos p=new BlockPos(x+width/2,81,z+length/2);w.setBlockState(p,ArchitectureBlocks.ARCHITECTS_WORKBENCH.getDefaultState(),3);return (ArchitectWorkbench.Desk)w.getTileEntity(p);}
    private void supply(int amount){for(int i=0;i<27&&amount>0;i++){int n=Math.min(64,amount);desk.setInventorySlotContents(i,new ItemStack(ArchitectureBlocks.ROOF_TIMBER,n,desk.drawing.wood));amount-=n;}require(amount==0,"fixture inventory fits");}
    private int liveTimber(){int n=0;for(long k:desk.drawing.cells.keySet()){BlockPos p=BlockPos.fromLong(k);RoofCell c=RoofData.get(world).at(world,p);if(c!=null&&c.timber()&&world.getBlockState(p).getBlock() instanceof RoofFrameBlock)n++;}return n;}
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent event){if(event.phase!=TickEvent.Phase.END)return;try{ticks++;if(ticks>1600)throw new IllegalStateException("Workbench probe timed out phase "+phase+" "+(desk==null?"":desk.status));int delta=(int)(RoofConstruction.changes-previousChanges);previousChanges=RoofConstruction.changes;if(phase>0){maxChanges=Math.max(maxChanges,delta);require(delta<=16,"global construction cap");}
        if(phase==0){
            if(Boolean.getBoolean("iaa.workbenchReload")){BlockPos bench=new BlockPos(1004,81,1005);desk=(ArchitectWorkbench.Desk)world.getTileEntity(bench);require(desk!=null,"saved bench");RoofPlan p=RoofData.get(world).find(bench.down());require(p!=null&&p.valid(),"saved drawing");for(Map.Entry<Long,RoofCell> e:p.cells.entrySet()){BlockPos at=BlockPos.fromLong(e.getKey());world.getChunkFromBlockCoords(at);RoofCell c=RoofData.get(world).at(world,at);require(c!=null&&c.equals(e.getValue()),"saved chunk descriptor "+at);require(world.getBlockState(at).getBlock() instanceof RoofFrameBlock,"saved frame "+at);}result.put("reload",true);finish();return;}
            desk=floor(world,1000,1000,8,11,0);RoofConstruction.detect(desk);desk.drawing.version=1;desk.drawing.base=1;RoofPlanner.solve(desk.drawing);require(desk.drawing.valid(),desk.drawing.error);require(RoofConstruction.validate(desk,desk.drawing,player).isEmpty(),RoofConstruction.validate(desk,desk.drawing,player));cost=RoofConstruction.required(desk,desk.drawing);require(!RoofConstruction.start(desk,player),"missing materials must refuse");require(liveTimber()==0,"refusal is unchanged");stock=cost;supply(stock);require(RoofConstruction.start(desk,player),desk.status);phase=1;
        }else if(phase==1&&desk.index>20){RoofConstruction.cancel(desk);require(desk.count(ArchitectureBlocks.ROOF_TIMBER,0)+liveTimber()==stock,"cancel conserves reserved timber");BlockPos blocked=null;for(long key:desk.drawing.cells.keySet())if(world.isAirBlock(BlockPos.fromLong(key))){blocked=BlockPos.fromLong(key);break;}require(blocked!=null,"unbuilt position exists");world.setBlockState(blocked,Blocks.STONE.getDefaultState(),3);require(!RoofConstruction.start(desk,player),"obstructed start refused");world.setBlockToAir(blocked);require(RoofConstruction.start(desk,player),desk.status);phase=2;
        }else if(phase==2&&!desk.active){require(liveTimber()==cost,"complete frame timber count");require(desk.remaining==0&&desk.count(ArchitectureBlocks.ROOF_TIMBER,0)==0,"no leftover or duplicated timber");result.put("initialTimber",cost);testCoverings();testMetadata();testRawSupplies();
            desk.drawing.pitch=0;desk.drawing.base=2;RoofPlanner.solve(desk.drawing);require(desk.drawing.valid(),desk.drawing.error);int needed=RoofConstruction.required(desk,desk.drawing);supply(needed);require(RoofConstruction.start(desk,player),desk.status);phase=3;
        }else if(phase==3&&desk.index>24){NBTTagCompound n=desk.writeToNBT(new NBTTagCompound());BlockPos at=desk.getPos();desk.invalidate();ArchitectWorkbench.Desk replacement=new ArchitectWorkbench.Desk();replacement.readFromNBT(n);world.setTileEntity(at,replacement);desk=replacement;desk.onLoad();phase=4;
        }else if(phase==4&&!desk.active){require(liveTimber()==desk.drawing.timber(),"resumed rework complete");require(desk.remaining==0,"resumed escrow consumed");result.put("reworkedTimber",liveTimber());result.put("returnedTimber",desk.count(ArchitectureBlocks.ROOF_TIMBER,0));result.put("maxChangesPerTick",maxChanges);result.put("maxConstructionWorkMs",RoofConstruction.maxWorkNanos/1e6);world.saveAllChunks(true,null);finish();}
    }catch(Throwable error){result.put("passed",false);result.put("error",error.toString());error.printStackTrace();write();server.initiateShutdown();}}
    private void testMetadata(){for(int wood=0;wood<6;wood++)for(int cover=0;cover<4;cover++){IBlockState s=RoofFrameBlock.state(wood,cover);require(s.equals(s.getBlock().getStateFromMeta(s.getBlock().getMetaFromState(s))),"frame metadata round trip");require(!net.minecraft.block.BlockPistonBase.canPush(s,world,desk.getPos().up(10),EnumFacing.EAST,false),"fixed roof geometry cannot be moved by pistons");}result.put("metadataStates",24);result.put("pistonProtected",true);}
    private void testCoverings(){RoofCell target=null;BlockPos at=null;for(Map.Entry<Long,RoofCell> e:desk.drawing.cells.entrySet())if(e.getValue().timber()&&e.getValue().coverable()){at=BlockPos.fromLong(e.getKey());target=e.getValue();break;}require(target!=null,"coverable frame");for(int cover=1;cover<=3;cover++){ItemStack item=RoofConstruction.coverItem(cover);if(item==null)continue;player.setSneaking(false);player.setHeldItem(EnumHand.MAIN_HAND,item);require(RoofConstruction.cover(world,at,player,item,EnumHand.MAIN_HAND),"apply cover");require(RoofFrameBlock.cover(world.getBlockState(at))==cover,"cover state");require(player.getHeldItemMainhand()==null,"one covering consumed");String rejection=RoofConstruction.validate(desk,desk.drawing,player);require(rejection.contains("Strip"),"covered rework rejected");player.setSneaking(true);require(RoofConstruction.cover(world,at,player,null,EnumHand.MAIN_HAND),"strip cover");require(RoofFrameBlock.cover(world.getBlockState(at))==0,"bare timber retained");player.inventory.clear();}
        player.setSneaking(false);ItemStack material=RoofConstruction.coverItem(1);if(material==null){result.put("independentOfRoofMaterials",true);return;}player.setHeldItem(EnumHand.MAIN_HAND,material);RoofConstruction.cover(world,at,player,material,EnumHand.MAIN_HAND);List<ItemStack> drops=world.getBlockState(at).getBlock().getDrops(world,at,world.getBlockState(at),0);int timber=0,cover=0;for(ItemStack s:drops){if(s.getItem()==ArchitectureBlocks.ROOF_TIMBER)timber+=s.stackSize;if(s.getItem()==Item.getItemFromBlock(ArchitectureBlocks.SMART_THATCH))cover+=s.stackSize;}require(timber==1&&cover==1,"mining through timber returns assembly once");player.interactionManager.setGameType(net.minecraft.world.GameType.SURVIVAL);player.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(Items.IRON_AXE));int beforeWood=dropped(at,ArchitectureBlocks.ROOF_TIMBER),beforeCover=dropped(at,Item.getItemFromBlock(ArchitectureBlocks.SMART_THATCH));require(player.interactionManager.tryHarvestBlock(at),"normal timber harvesting");require(dropped(at,ArchitectureBlocks.ROOF_TIMBER)==beforeWood+1&&dropped(at,Item.getItemFromBlock(ArchitectureBlocks.SMART_THATCH))==beforeCover+1,"native mining returns both paid materials once");require(RoofData.get(world).at(world,at)==null,"mining cleans descriptor");
        for(int operation=0;operation<3;operation++){BlockPos helper=null;RoofCell link=null;for(long key:desk.drawing.cells.keySet()){BlockPos candidate=BlockPos.fromLong(key);RoofCell c=RoofData.get(world).at(world,candidate);if(c!=null&&!c.timber()&&c.coverable()&&world.getBlockState(candidate).getBlock() instanceof RoofFrameBlock){RoofCell owner=RoofData.get(world).at(world,c.owner);if(owner!=null&&owner.timber()&&owner.coverable()){helper=candidate;link=c;break;}}}require(helper!=null,"helper fixture");BlockPos owner=link.owner;ItemStack covering=RoofConstruction.coverItem(1);player.setHeldItem(EnumHand.MAIN_HAND,covering);RoofConstruction.cover(world,owner,player,covering,EnumHand.MAIN_HAND);require(RoofFrameBlock.cover(world.getBlockState(helper))==1,"covered helper linked");int woodBefore=dropped(helper,ArchitectureBlocks.ROOF_TIMBER),coverBefore=dropped(helper,Item.getItemFromBlock(ArchitectureBlocks.SMART_THATCH));if(operation==0){player.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(Items.IRON_AXE));require(player.interactionManager.tryHarvestBlock(helper),"harvesting helper succeeds");require(dropped(helper,ArchitectureBlocks.ROOF_TIMBER)==woodBefore+1&&dropped(helper,Item.getItemFromBlock(ArchitectureBlocks.SMART_THATCH))==coverBefore+1,"helper harvest has exactly one assembly drop");}else if(operation==1){world.getBlockState(helper).getBlock().onBlockExploded(world,helper,null);require(dropped(helper,ArchitectureBlocks.ROOF_TIMBER)==woodBefore+1&&dropped(helper,Item.getItemFromBlock(ArchitectureBlocks.SMART_THATCH))==coverBefore+1,"helper explosion drops assembly once");}else{world.setBlockState(helper,Blocks.STONE.getDefaultState(),3);require(world.getBlockState(helper).getBlock()==Blocks.STONE,"forced replacement preserved");require(world.getBlockState(owner).getBlock() instanceof RoofFrameBlock,"unrelated timber retained after replacement");world.setBlockToAir(helper);}}
        BlockPos interior=null,roof=null;for(long key:desk.drawing.cells.keySet()){BlockPos candidate=BlockPos.fromLong(key);RoofCell c=RoofData.get(world).at(world,candidate);if(c!=null&&c.timber()&&!c.coverable()){RoofCell owner=RoofData.get(world).at(world,c.owner);if(owner!=null&&owner.coverable()&&world.getBlockState(c.owner).getBlock() instanceof RoofFrameBlock){interior=candidate;roof=c.owner;break;}}}require(interior!=null,"interior collar fixture");ItemStack top=RoofConstruction.coverItem(1);player.setHeldItem(EnumHand.MAIN_HAND,top);RoofConstruction.cover(world,roof,player,top,EnumHand.MAIN_HAND);require(RoofFrameBlock.cover(world.getBlockState(roof))==1,"interior fixture roof covered");player.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(Items.IRON_AXE));require(player.interactionManager.tryHarvestBlock(interior),"interior beam harvested");require(RoofFrameBlock.cover(world.getBlockState(roof))==1,"interior beam removal preserves roof covering");player.setHeldItem(EnumHand.MAIN_HAND,null);player.setSneaking(true);RoofConstruction.cover(world,roof,player,null,EnumHand.MAIN_HAND);player.setSneaking(false);result.put("interiorBeamPreservesCovering",true);result.put("nativeHarvestAndCleanup",true);result.put("coverings",3);
    }
    private int dropped(BlockPos p,Item item){int n=0;for(EntityItem e:world.getEntitiesWithinAABB(EntityItem.class,new AxisAlignedBB(p.add(-3,-3,-3),p.add(4,4,4))))if(e.getEntityItem().getItem()==item)n+=e.getEntityItem().stackSize;return n;}
    private void testRawSupplies(){ArchitectWorkbench.Desk other=floor(world,1040,1000,4,4,5);RoofConstruction.detect(other);other.drawing.version=1;RoofPlanner.solve(other.drawing);ItemStack forged=new ItemStack(ArchitectureBlocks.ARCHITECTS_WORKBENCH);NBTTagCompound outer=new NBTTagCompound(),job=new NBTTagCompound();job.setBoolean("active",true);job.setInteger("remaining",1024);outer.setTag("BlockEntityTag",job);forged.setTagCompound(outer);require(!player.canUseCommandBlock(),"test actor is not an operator");require(!ItemBlock.setTileEntityNBT(world,player,other.getPos(),forged)&&!other.active&&other.remaining==0,"untrusted item NBT cannot inject construction");NBTTagCompound client=other.getUpdateTag();require(!client.hasKey("drawing")&&!client.hasKey("items")&&!client.hasKey("remaining"),"chunk updates omit private workbench jobs and inventory");result.put("itemNbtProtected",true);int needed=RoofConstruction.required(other,other.drawing),pairs=(needed+1)/2;other.setInventorySlotContents(0,new ItemStack(Blocks.PLANKS,pairs,5));other.setInventorySlotContents(1,new ItemStack(Items.STICK,pairs));require(RoofConstruction.start(other,player),other.status);RoofConstruction.cancel(other);require(other.count(ArchitectureBlocks.ROOF_TIMBER,5)==pairs*2,"raw supplies preserve the odd conversion remainder");require(other.count(Item.getItemFromBlock(Blocks.PLANKS),5)==0&&other.count(Items.STICK,-1)==0,"only reserved pairs consumed");int before=dropped(other.getPos(),ArchitectureBlocks.ROOF_TIMBER);world.destroyBlock(other.getPos(),true);require(dropped(other.getPos(),ArchitectureBlocks.ROOF_TIMBER)==before+pairs*2,"breaking bench returns its stock once");result.put("rawSupplyAndBenchRecovery",true);}
    private void finish(){result.put("passed",true);result.put("runtimeSha256",System.getProperty("iaa.runtimeSha256"));write();System.out.println("IAA_WORKBENCH_PROBE_PASS "+result);server.initiateShutdown();}
    private void write(){try{Path file=Paths.get(System.getProperty("iaa.receipt","workbench-receipt.json"));Files.write(file,new GsonBuilder().setPrettyPrinting().create().toJson(result).getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){throw new RuntimeException(e);}}
}
